    cl_కార్యక్రమం కార్యక్రమం_mul_mv_q4_0_f32_v;
    cl_కార్యక్రమం కార్యక్రమం_mul_mv_q4_0_f32_8x_flat;
    cl_కార్యక్రమం కార్యక్రమం_mul_mv_q4_0_f32_1d_8x_flat;
    cl_కార్యక్రమం కార్యక్రమం_mul_mv_q4_0_f32_1d_16x_flat;
    cl_కార్యక్రమం కార్యక్రమం_mul_mv_q6_K;
    cl_కార్యక్రమం కార్యక్రమం_mul_mv_q8_0_f32, కార్యక్రమం_mul_mv_q8_0_f32_flat;
    cl_కార్యక్రమం కార్యక్రమం_mul_mv_mxfp4_f32;
