        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 4, పరిమాణం(cl_mem),   &extra->d));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 5, పరిమాణం(cl_mem),   &extra->dm));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 6, పరిమాణం(cl_uchar), &ముసుగు_0_F));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 7, పరిమాణం(cl_uchar), &ముసుగు_F0));

        size_t global_work_కొలత[] = {(size_t)ggml_nelements(tensor)/ggml_blck_కొలత(tensor->type), 1, 1};
        size_t local_work_కొలత[] = {64, 1, 1};

        cl_event evt;
        CL_CHECK(cl_వరుసలో_చేర్చు_NDRange_Kernel(queue, kernel, 3, ఖాళీ, global_work_కొలత, local_work_కొలత, 0, ఖాళీ, &evt));
        CL_CHECK(clWaitForEvents(1, &evt));
        CL_CHECK(clReleaseMemObject(దత్తాంశం_device));

