        ggml_backend_opencl_బఫరు_context * ctx = (ggml_backend_opencl_బఫరు_context *) బఫరు->context;
        ggml_tensor_extra_cl_q6_K * extra = ctx->ggml_opencl_alloc_తాత్కాలిక_tensor_extra_q6_K();

        size_t కొలత_ql = ggml_nelements(tensor)/ggml_blck_కొలత(tensor->type)*ggml_blck_కొలత(tensor->type)/2;
        size_t కొలత_qh = ggml_nelements(tensor)/ggml_blck_కొలత(tensor->type)*ggml_blck_కొలత(tensor->type)/4;
        size_t కొలత_s  = ggml_nelements(tensor)/ggml_blck_కొలత(tensor->type)*ggml_blck_కొలత(tensor->type)/16;
