            CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 6, పరిమాణం(పూర్ణాంకం), &ne01));

            size_t global_work_కొలత[] = {static_cast<size_t>(((ne01 + 63) / 64) * 64), static_cast<size_t>(ne00 / 256), static_cast<size_t>(ne02)};
            size_t local_work_కొలత[] = {64, 1, 1};

