        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 1, పరిమాణం(cl_mem),   &extra->ql));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 2, పరిమాణం(cl_mem),   &extra->qh));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 3, పరిమాణం(cl_mem),   &extra->s));
