        CL_CHECK(cl_వరుసలో_చేర్చు_NDRange_Kernel(queue, kernel, 3, ఖాళీ, global_work_కొలత, local_work_కొలత, 0, ఖాళీ, &evt));
        CL_CHECK(clWaitForEvents(1, &evt));
        CL_CHECK(clReleaseMemObject(దత్తాంశం_device));

        extra->కొలత_ql = కొలత_ql;
        extra->కొలత_qh = కొలత_qh;
        extra->కొలత_s  = కొలత_s;
        extra->కొలత_d  = కొలత_d;

