                transpose_2d_as_8b(backend_ctx,  extra->qh, buf_trans_qh.బఫరు, కొలత_qh, M, K/4);
                transpose_2d_as_16b(backend_ctx, extra->s,  buf_trans_s.బఫరు,  కొలత_s,  M, K/16/2);
