            CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 1, పరిమాణం(cl_mem),   &buf_trans_qh.బఫరు));
            CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 2, పరిమాణం(cl_mem),   &s_బఫరు));
            CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 3, పరిమాణం(cl_mem),   &buf_trans_d.బఫరు));
