            CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 5, పరిమాణం(cl_uchar), &ముసుగు));
            CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 6, పరిమాణం(cl_ulong), &n_blk));

