            size_t local_work_కొలత[] = {1, 1, 1};

            cl_event evt;
            CL_CHECK(cl_వరుసలో_చేర్చు_NDRange_Kernel(queue, kernel, 3, ఖాళీ, global_work_కొలత, local_work_కొలత, 0, ఖాళీ, &evt));
            CL_CHECK(clWaitForEvents(1, &evt));
            CL_CHECK(cl_వరుసలో_చేర్చు_Read_బఫరు(queue, buf_unpacked.బఫరు, CL_TRUE, స్థానభ్రంశం, size, దత్తాంశం, 0, ఖాళీ, ఖాళీ));

            తిరిగి;
