        cl_ulong n_blk = ggml_nelements(tensor)/ggml_blck_కొలత(tensor->type);
        cl_kernel kernel = backend_ctx->kernel_restore_ఖండం_q6_K;
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 0, పరిమాణం(cl_mem),   &extra->ql));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 1, పరిమాణం(cl_mem),   &extra->qh));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 2, పరిమాణం(cl_mem),   &extra->s));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 3, పరిమాణం(cl_mem),   &extra->d));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 4, పరిమాణం(cl_mem),   &దత్తాంశం_device));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 5, పరిమాణం(cl_uchar), &ముసుగు));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 6, పరిమాణం(cl_ulong), &n_blk));

        size_t global_work_కొలత[] = {(size_t)n_blk, 1, 1};
        size_t local_work_కొలత[] = {1, 1, 1};

        cl_event evt;
        CL_CHECK(cl_వరుసలో_చేర్చు_NDRange_Kernel(queue, kernel, 3, ఖాళీ,
            global_work_కొలత, local_work_కొలత, 0, ఖాళీ, &evt));
        CL_CHECK(clWaitForEvents(1, &evt));
        CL_CHECK(cl_వరుసలో_చేర్చు_Read_బఫరు(
            queue, దత్తాంశం_device, CL_TRUE, స్థానభ్రంశం,
            size, దత్తాంశం, 0, ఖాళీ, ఖాళీ));
        CL_CHECK(clReleaseMemObject(దత్తాంశం_device));
