        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 1, పరిమాణం(cl_ulong), &off_src));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 2, పరిమాణం(cl_mem), &దత్తాంశం_device));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 3, పరిమాణం(cl_ulong), &n_elements));

