    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 0, పరిమాణం(cl_mem),   &extra0->దత్తాంశం_device));
    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 1, పరిమాణం(cl_ulong), &offset0));
    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 2, పరిమాణం(cl_mem),   &extrad->దత్తాంశం_device));
    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 3, పరిమాణం(cl_ulong), &offsetd));

    size_t global_work_కొలత[] = {(size_t)n, 1, 1};
