        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 1, పరిమాణం(cl_mem), &b_img_trans));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 2, పరిమాణం(పూర్ణాంకం),    &ఎత్తు_B));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 3, పరిమాణం(పూర్ణాంకం),    &వెడల్పు_B));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 4, పరిమాణం(పూర్ణాంకం),    &padded_ఎత్తు_B));

        size_t local_work_కొలత_t[2] = { 1, 16 };
