        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 5, పరిమాణం(cl_mem),   &extrad->దత్తాంశం_device));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 6, పరిమాణం(cl_ulong), &offsetd));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 7, పరిమాణం(cl_int),   &ne00));
        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 8, పరిమాణం(cl_int),   &ne01));

        size_t local_work_కొలత[3] = {64, 4, 1};
