        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 6, పరిమాణం(cl_int),   &ne01));

        size_t local_work_కొలత[3] = {64, 4, 1};
        size_t global_work_కొలత[3] = {(size_t)CEIL_DIV(ne01/2, 64)*64, 4, 1};

