        backend_ctx->వరుసలో_చేర్చు_ndrange_kernel(kernel, 2, global_work_కొలత_t, local_work_కొలత_t, dst);

        // gemm
        kernel = backend_ctx->kernel_gemm_noshuffle_iq4_nl_f32;
        పూర్ణాంకం padded_N = N + padding;

        CL_CHECK(cl_సమితి_Kernel_Arg(kernel, 0, పరిమాణం(cl_mem),   &extra0_iq4_nl->q));
