                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(cl_mem),   &K_img));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(cl_mem),   &extra1->దత్తాంశం_device));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(cl_ulong), &offset1));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(cl_mem),   &extrad->దత్తాంశం_device));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(cl_ulong), &offsetd));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(పూర్ణాంకం),      &ne00));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(పూర్ణాంకం),      &ne01));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(పూర్ణాంకం),      &ne02));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(cl_ulong), &nb01));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(cl_ulong), &nb02));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(cl_ulong), &nb03));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(పూర్ణాంకం),      &ne10));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(పూర్ణాంకం),      &ne11));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(పూర్ణాంకం),      &ne12));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(cl_ulong), &nb10));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(cl_ulong), &nb11));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(cl_ulong), &nb12));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(cl_ulong), &nb13));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, k_arg++, పరిమాణం(పూర్ణాంకం),      &ne0));
