                        CL_CHECK(cl_సమితి_Kernel_Arg(dk, aidx++, పరిమాణం(cl_mem), &backend_ctx->prealloc_moe_qa.బఫరు));
                        CL_CHECK(cl_సమితి_Kernel_Arg(dk, aidx++, పరిమాణం(cl_mem), &backend_ctx->prealloc_moe_da.బఫరు));
