                        CL_CHECK(cl_సమితి_Kernel_Arg(rq, 3, పరిమాణం(cl_mem),         &backend_ctx->prealloc_moe_da.బఫరు));
                        CL_CHECK(cl_సమితి_Kernel_Arg(rq, 4, పరిమాణం(cl_mem),         &backend_ctx->prealloc_moe_sa.బఫరు));
