                        CL_CHECK(cl_సమితి_Kernel_Arg(dk, qi++, పరిమాణం(cl_mem), &extra0_q6_K->d));
                        CL_CHECK(cl_సమితి_Kernel_Arg(dk, qi++, పరిమాణం(cl_mem), &backend_ctx->prealloc_moe_qa.బఫరు));
                        CL_CHECK(cl_సమితి_Kernel_Arg(dk, qi++, పరిమాణం(cl_mem), &backend_ctx->prealloc_moe_da.బఫరు));
