                        CL_CHECK(cl_సమితి_Kernel_Arg(dk, qi++, పరిమాణం(cl_mem), &buf_src2_emap));
                        CL_CHECK(cl_సమితి_Kernel_Arg(dk, qi++, పరిమాణం(cl_mem), &buf_dst_image));
