                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, arg_idx++, పరిమాణం(cl_mem),    &extrad->దత్తాంశం_device));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, arg_idx++, పరిమాణం(cl_ulong),  &offsetd));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, arg_idx++, పరిమాణం(పూర్ణాంకం),       &ne00));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, arg_idx++, పరిమాణం(పూర్ణాంకం),       &ne01));
                    CL_CHECK(cl_సమితి_Kernel_Arg(kernel, arg_idx++, పరిమాణం(పూర్ణాంకం),       &ne11));

